PRAGMA temp_store=MEMORY;
CREATE TEMP TABLE t AS SELECT event_time_s, domain, client_ip, client_name, source_id, status, status_code, query_type, query_type_code FROM queries;
.timer on
CREATE INDEX temp.ty ON t((CAST(event_time_s AS INTEGER) / 900), source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code, event_time_s);
CREATE INDEX temp.tk ON t(source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code, event_time_s);
CREATE INDEX temp.tc ON t((CAST(event_time_s AS INTEGER) / 900), source_id, status, status_code, event_time_s);
SELECT 'Y_wide_cells', COUNT(*), SUM(n) FROM (SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code, COUNT(*) AS n FROM t INDEXED BY ty WHERE (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 AND NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY c, source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code);
EXPLAIN QUERY PLAN SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code, COUNT(*) AS n FROM t INDEXED BY ty WHERE (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 AND NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY c, source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code;
SELECT 'K_wide', COUNT(*) FROM (SELECT source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code, COUNT(*) FROM t INDEXED BY tk WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY source_id, client_ip, client_name, domain, status, status_code, query_type, query_type_code);
SELECT 'K_clients', COUNT(*) FROM (SELECT source_id, client_ip, client_name, domain, status, status_code, COUNT(*), MIN(event_time_s), MAX(event_time_s) FROM t INDEXED BY tk WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY source_id, client_ip, client_name, domain, status, status_code);
SELECT 'K_identity', COUNT(*) FROM (SELECT DISTINCT source_id, client_ip, client_name FROM t INDEXED BY tk WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626);
SELECT 'C_timeline', COUNT(*) FROM (SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, status, status_code, COUNT(*) FROM t INDEXED BY tc WHERE (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 AND NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY c, source_id, status, status_code);
EXPLAIN QUERY PLAN SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, status, status_code, COUNT(*) FROM t INDEXED BY tc WHERE (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 AND NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY c, source_id, status, status_code;
